arguments.content:
:root {
  /* Brand Colors */
  --primary-black: #000000;
  --accent-green: #55DA9B;
  --accent-purple: #5620C1;

  /* UI Colors */
  --navy: #0A1128;
  --navy-dark: #050814;
  --coral: #FF6B6B;
  --yellow: #FCA311;
  --white: #FFFFFF;
  --bg-light: #F8F9FA;
  --bg-gray: #F1F3F5;
  --text-dark: #1A1D20;
  --text-gray: #495057;
  --text-light: #E9ECEF;
  --border-light: #DEE2E6;

  /* Typography */
  --font-heading: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;

  /* Effects */
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.04);
  --shadow-md: 0 8px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 16px 48px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-pill: 9999px;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  color: var(--text-dark);
  background-color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Utilities */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 96px 0;
}

.section-title {
  font-size: 2.5rem;
  margin-bottom: 48px;
  text-align: center;
}

.section-subtitle {
  font-size: 1.25rem;
  color: var(--text-gray);
  text-align: center;
  margin-top: -32px;
  margin-bottom: 64px;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 28px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  border-radius: var(--radius-pill);
  cursor: pointer;
  transition: var(--transition);
  border: 2px solid transparent;
  text-align: center;
}

.btn-primary {
  background-color: var(--accent-green);
  color: var(--primary-black);
}

.btn-primary:hover {
  background-color: #4BC28A;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(85, 218, 155, 0.4);
}

.btn-outline {
  background-color: transparent;
  color: var(--white);
  border-color: rgba(255, 255, 255, 0.2);
}

.btn-outline:hover {
  border-color: var(--white);
  background-color: rgba(255, 255, 255, 0.1);
}

.btn-google {
  background-color: var(--white);
  color: var(--primary-black);
  gap: 12px;
}

.btn-google:hover {
  background-color: var(--bg-light);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(255,255,255,0.2);
}

/* Header */
.header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 24px 0;
}

.header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.03em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo span {
  color: var(--accent-green);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  color: var(--white);
  font-weight: 600;
  font-size: 1rem;
  transition: var(--transition);
}

.nav-link:hover {
  color: var(--accent-green);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Hero */
.hero {
  background-color: var(--navy);
  background-image: radial-gradient(circle at 80% 20%, rgba(86, 32, 193, 0.4) 0%, transparent 40%),
                    radial-gradient(circle at 20% 80%, rgba(85, 218, 155, 0.2) 0%, transparent 40%);
  color: var(--white);
  padding: 180px 0 80px;
  position: relative;
  overflow: hidden;
  text-align: center;
}

.hero-content {
  max-width: 800px;
  margin: 0 auto 64px;
  position: relative;
  z-index: 2;
}

.hero h1 {
  font-size: 4.5rem;
  margin-bottom: 24px;
  line-height: 1.05;
}

.hero p.subtitle {
  font-size: 1.5rem;
  color: var(--text-light);
  margin-bottom: 40px;
  font-weight: 500;
}

.hero-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.cta-group {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.legal-note {
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.5);
  max-width: 500px;
  margin-top: 24px;
  line-height: 1.5;
}

/* Marquee */
.marquee-container {
  width: 100%;
  overflow: hidden;
  position: relative;
  padding: 24px 0;
  background: rgba(255, 255, 255, 0.05);
  border-top: 1px solid rgba(255,255,255,0.1);
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.marquee-content {
  display: flex;
  width: max-content;
  animation: scroll 30s linear infinite;
  gap: 16px;
}

.marquee-content:hover {
  animation-play-state: paused;
}

.category-pill {
  padding: 12px 24px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 1rem;
  color: var(--white);
  white-space: nowrap;
  backdrop-filter: blur(4px);
  cursor: pointer;
  transition: var(--transition);
}

.category-pill:hover {
  background: var(--accent-green);
  color: var(--primary-black);
  transform: scale(1.05);
}

@keyframes scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(calc(-50% - 8px)); }
}

/* Value Props */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 32px;
}

.feature-card {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  border: 1px solid var(--border-light);
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: var(--accent-green);
}

.feature-icon {
  width: 64px;
  height: 64px;
  background: var(--bg-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
  color: var(--accent-purple);
}

.feature-icon svg {
  width: 32px;
  height: 32px;
}

.feature-card h3 {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--text-gray);
  font-size: 0.95rem;
}

/* Stats */
.stats-section {
  background-color: var(--accent-green);
  color: var(--primary-black);
  padding: 80px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  text-align: center;
}

.stat-item h3 {
  font-size: 4rem;
  font-weight: 800;
  margin-bottom: 8px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.stat-item p {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 1rem;
}

/* Courses */
.courses-section {
  background-color: var(--bg-light);
}

.course-tabs {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 16px;
  margin-bottom: 40px;
  scrollbar-width: none;
}

.course-tabs::-webkit-scrollbar {
  display: none;
}

.course-tab {
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  cursor: pointer;
  background: var(--white);
  color: var(--text-gray);
  border: 1px solid var(--border-light);
  white-space: nowrap;
  transition: var(--transition);
}

.course-tab:hover {
  border-color: var(--primary-black);
  color: var(--primary-black);
}

.course-tab.active {
  background: var(--primary-black);
  color: var(--white);
  border-color: var(--primary-black);
}

.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 32px;
}

.course-card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  cursor: pointer;
  display: flex;
  flex-direction: column;
}

.course-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
}

.course-thumb {
  position: relative;
  aspect-ratio: 16/9;
  background: var(--bg-gray);
  overflow: hidden;
}

.course-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.course-card:hover .course-thumb img {
  transform: scale(1.05);
}

.course-duration {
  position: absolute;
  bottom: 12px;
  right: 12px;
  background: rgba(0,0,0,0.8);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 4px 8px;
  border-radius: 4px;
}

.course-info {
  padding: 20px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.course-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 8px;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  flex: 1;
}

.course-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 16px;
  font-size: 0.875rem;
  color: var(--text-gray);
}

.course-author {
  font-weight: 600;
  color: var(--primary-black);
}

.course-students {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Creative Feed */
.creative-feed {
  background-color: var(--white);
}

.feed-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 40px;
}

.feed-item {
  position: relative;
  padding: 40px;
  border-radius: var(--radius-lg);
  background: var(--bg-light);
  overflow: hidden;
  z-index: 1;
}

.feed-item::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  z-index: -1;
  opacity: 0.1;
  background-size: cover;
  background-position: center;
  transition: opacity 0.3s ease;
}

.feed-item:nth-child(1) { background-color: #FFF0F0; }
.feed-item:nth-child(2) { background-color: #F0F4FF; }
.feed-item:nth-child(3) { background-color: #F0FFF4; }

.feed-item h3 {
  font-size: 1.75rem;
  margin-bottom: 16px;
}

.feed-item p {
  color: var(--text-gray);
  margin-bottom: 24px;
  font-size: 1.05rem;
}

/* Teachers Carousel */
.teachers-section {
  background-color: var(--primary-black);
  color: var(--white);
  overflow: hidden;
}

.teachers-section .section-title,
.teachers-section .section-subtitle {
  color: var(--white);
}

.teachers-carousel {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  padding: 24px 0 48px;
  scroll-snap-type: x mandatory;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.3) transparent;
}

.teachers-carousel::-webkit-scrollbar {
  height: 8px;
}
.teachers-carousel::-webkit-scrollbar-track {
  background: rgba(255,255,255,0.1);
  border-radius: 4px;
}
.teachers-carousel::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.3);
  border-radius: 4px;
}

.teacher-card {
  min-width: 280px;
  scroll-snap-align: start;
  background: rgba(255,255,255,0.05);
  border-radius: var(--radius-md);
  padding: 32px 24px;
  text-align: center;
  border: 1px solid rgba(255,255,255,0.1);
  transition: var(--transition);
}

.teacher-card:hover {
  background: rgba(255,255,255,0.1);
  transform: translateY(-4px);
}

.teacher-photo {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto 20px;
  object-fit: cover;
  border: 4px solid var(--accent-purple);
}

.teacher-name {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.teacher-specialty {
  color: var(--accent-green);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Testimonials */
.testimonials {
  background-color: var(--bg-light);
}

.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
}

.testimonial-card {
  background: var(--white);
  padding: 32px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
}

.quote-icon {
  color: var(--accent-green);
  font-size: 2rem;
  margin-bottom: 16px;
  line-height: 1;
}

.testimonial-text {
  font-size: 1.125rem;
  font-style: italic;
  margin-bottom: 24px;
  flex: 1;
}

.testimonial-author {
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 12px;
}

.author-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bg-gray);
  object-fit: cover;
}

/* Teams */
.teams-section {
  margin: 0 24px;
  padding: 0;
}

.teams-banner {
  background-color: var(--accent-purple);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 80px 40px;
  text-align: center;
  position: relative;
  overflow: hidden;
  max-width: 1280px;
  margin: 0 auto;
}

.teams-banner::before {
  content: '';
  position: absolute;
  top: -50%; left: -10%;
  width: 300px; height: 300px;
  background: var(--coral);
  border-radius: 50%;
  filter: blur(100px);
  opacity: 0.5;
}

.teams-banner::after {
  content: '';
  position: absolute;
  bottom: -50%; right: -10%;
  width: 300px; height: 300px;
  background: var(--yellow);
  border-radius: 50%;
  filter: blur(100px);
  opacity: 0.5;
}

.teams-content {
  position: relative;
  z-index: 2;
  max-width: 700px;
  margin: 0 auto;
}

.teams-banner h2 {
  font-size: 3rem;
  margin-bottom: 24px;
}

.teams-banner p {
  font-size: 1.25rem;
  margin-bottom: 40px;
  opacity: 0.9;
}

/* FAQ */
.faq-section {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-light);
}

.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 24px 0;
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--primary-black);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: var(--transition);
}

.faq-question:hover {
  color: var(--accent-purple);
}

.faq-icon {
  width: 24px;
  height: 24px;
  position: relative;
  transition: transform 0.3s ease;
}

.faq-icon::before, .faq-icon::after {
  content: '';
  position: absolute;
  background-color: currentColor;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
}

.faq-icon::before { width: 16px; height: 2px; }
.faq-icon::after { width: 2px; height: 16px; transition: transform 0.3s ease; }

.faq-item.active .faq-icon::after { transform: translate(-50%, -50%) rotate(90deg); opacity: 0; }
.faq-item.active .faq-question { color: var(--accent-purple); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-answer-inner {
  padding-bottom: 24px;
  color: var(--text-gray);
  line-height: 1.8;
}

/* Footer */
.footer {
  background-color: var(--navy-dark);
  color: var(--white);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  margin-bottom: 64px;
}

.footer-col h4 {
  font-size: 1.125rem;
  margin-bottom: 24px;
  color: var(--white);
}

.footer-col ul li {
  margin-bottom: 12px;
}

.footer-col a {
  color: var(--text-light);
  opacity: 0.7;
  transition: var(--transition);
  font-size: 0.9rem;
}

.footer-col a:hover {
  opacity: 1;
  color: var(--accent-green);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 32px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
  text-align: center;
}

.footer-disclaimer {
  font-size: 0.75rem;
  color: rgba(255,255,255,0.4);
  max-width: 800px;
}

/* Responsive */
@media (max-width: 768px) {
  .hero h1 { font-size: 3rem; }
  .hero { padding: 140px 0 60px; }
  .section { padding: 64px 0; }
  .teams-banner { padding: 40px 24px; }
  .teams-banner h2 { font-size: 2rem; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .nav-links { display: none; } /* Simplified for mobile */
}

document.addEventListener('DOMContentLoaded', () => {

  // 1. FAQ Accordion Logic
  const faqItems = document.querySelectorAll('.faq-item');

  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    const answer = item.querySelector('.faq-answer');
    const answerInner = item.querySelector('.faq-answer-inner');

    question.addEventListener('click', () => {
      const isActive = item.classList.contains('active');

      // Close all
      faqItems.forEach(i => {
        i.classList.remove('active');
        i.querySelector('.faq-answer').style.maxHeight = null;
      });

      // Toggle current
      if (!isActive) {
        item.classList.add('active');
        answer.style.maxHeight = answerInner.scrollHeight + 'px';
      }
    });
  });

  // 2. Course Category Tabs Logic (Simulation)
  const courseTabs = document.querySelectorAll('.course-tab');
  const courseCards = document.querySelectorAll('.course-card');

  courseTabs.forEach(tab => {
    tab.addEventListener('click', () => {
      // Remove active from all tabs
      courseTabs.forEach(t => t.classList.remove('active'));
      // Add active to clicked tab
      tab.classList.add('active');

      const category = tab.dataset.category;

      // Simple visual transition simulation for filtering
      courseCards.forEach(card => {
        card.style.opacity = '0.5';
        card.style.transform = 'scale(0.98)';
      });

      setTimeout(() => {
        courseCards.forEach(card => {
          const cardCat = card.dataset.category;

          if (category === 'All' || category === 'Featured') {
            card.style.display = 'flex';
          } else {
            // Since we only have static demo data, we randomly show/hide to simulate filtering
            // In a real app, this would match `cardCat === category`
            const shouldShow = Math.random() > 0.3; 
            card.style.display = shouldShow ? 'flex' : 'none';
          }

          setTimeout(() => {
            card.style.opacity = '1';
            card.style.transform = 'scale(1)';
          }, 50);
        });
      }, 200);
    });
  });

  // 3. Hero Sign-up buttons logic
  const googleBtn = document.getElementById('signup-google');
  const emailBtn = document.getElementById('signup-email');

  if (googleBtn) {
    googleBtn.addEventListener('click', (e) => {
      e.preventDefault();
      console.log('Interaction [hero-signup-google]: Initiating Google OAuth flow...');
      alert('Initiating Google sign-up flow...');
    });
  }

  if (emailBtn) {
    emailBtn.addEventListener('click', (e) => {
      e.preventDefault();
      console.log('Interaction [hero-signup-email]: Opening email sign-up modal...');
      alert('Opening email sign-up form...');
    });
  }

  // 4. Header interactions
  const authLinks = document.querySelectorAll('header a[href="#"]');
  authLinks.forEach(link => {
    link.addEventListener('click', (e) => {
      e.preventDefault();
      const text = e.target.textContent;
      console.log(`Navigation triggered: ${text}`);
      if(text.includes('Sign In') || text.includes('Sign Up')) {
        alert(`${text} modal opened.`);
      }
    });
  });

  // 5. Duplicate Marquee content for seamless scroll
  const marquee = document.querySelector('.marquee-content');
  if (marquee) {
    const clone = marquee.cloneNode(true);
    // Move all items from clone to original marquee to make it double length
    Array.from(clone.children).forEach(child => {
      marquee.appendChild(child);
    });
  }
});
